package dev.DraGonFiirE.littleperformanceimprovements.client.render;
import java.util.*;import team.creative.littletiles.common.math.box.*;import team.creative.littletiles.common.math.box.collection.*;import team.creative.littletiles.common.placement.shape.LittleShape;import team.creative.littletiles.common.placement.shape.type.LittleShapePolygon;import team.creative.littletiles.client.render.overlay.PreviewRenderer;
public final class PolygonDragFaces {
 private static final ThreadLocal<LittleBoxes> active=new ThreadLocal<>();
 public static List<int[]> extract(LittleBoxes boxes){active.set(boxes);try{return faces(boxes);}finally{active.remove();}}
 public static List<int[]> faces(LittleBoxes boxes){if(active.get()!=boxes)return null;PolygonVoxelContext.current.remove();int[] min={Integer.MAX_VALUE,Integer.MAX_VALUE,Integer.MAX_VALUE},max={Integer.MIN_VALUE,Integer.MIN_VALUE,Integer.MIN_VALUE};long volume=0;for(var b:boxes.all()){if(b.getClass()!=LittleBox.class)return null;long x=(long)b.maxX-b.minX,y=(long)b.maxY-b.minY,z=(long)b.maxZ-b.minZ;if(x<=0||y<=0||z<=0||x>500000||y>500000||z>500000||x*y>500000||x*y*z>500000)return null;volume+=x*y*z;if(volume>500000)return null;min[0]=Math.min(min[0],b.minX);min[1]=Math.min(min[1],b.minY);min[2]=Math.min(min[2],b.minZ);max[0]=Math.max(max[0],b.maxX);max[1]=Math.max(max[1],b.maxY);max[2]=Math.max(max[2],b.maxZ);}if(volume==0)return new ArrayList<>();long sy=(long)max[1]-min[1]+2,sz=(long)max[2]-min[2]+2,sx=(long)max[0]-min[0]+2;if(sy>1000000||sz>1000000||sx>1000000)return null;long yz=sy*sz;var cells=new it.unimi.dsi.fastutil.longs.LongOpenHashSet((int)volume*4);var keys=new it.unimi.dsi.fastutil.longs.LongArrayList((int)volume);for(var b:boxes.all())for(int x=b.minX;x<b.maxX;x++)for(int y=b.minY;y<b.maxY;y++)for(int z=b.minZ;z<b.maxZ;z++){long key=((long)x-min[0]+1)*yz+((long)y-min[1]+1)*sz+(long)z-min[2]+1;if(cells.add(key))keys.add(key);}long[] strides={yz,sz,1};var result=new ArrayList<int[]>();for(int ki=0;ki<keys.size();ki++){long key=keys.getLong(ki);int[] pos={(int)(key/yz)+min[0]-1,(int)((key%yz)/sz)+min[1]-1,(int)(key%sz)+min[2]-1};int neighbors=0;for(int axis=0;axis<3;axis++)for(int sign=0;sign<2;sign++)if(cells.contains(key+(sign==0?-strides[axis]:strides[axis])))neighbors|=1<<(axis*2+sign);for(int axis=0;axis<3;axis++)for(int sign=0;sign<2;sign++)if((neighbors&(1<<(axis*2+sign)))==0){int u=(axis+1)%3,v=(axis+2)%3;result.add(new int[]{axis,sign,pos[axis]+sign,u,v,pos[u],pos[u]+1,pos[v],pos[v]+1,neighbors});}}PolygonVoxelContext.current.set(new PolygonVoxelContext(cells,min,sy,sz));return result;}
 public static PreviewRenderer.BoxRenderResult surface(PreviewRenderer renderer,LittleBoxes boxes,LittleShape shape){if(!(shape instanceof LittleShapePolygon))return DragExteriorMesh.build(renderer,boxes);active.set(boxes);try{var faces=faces(boxes);return faces==null?DragExteriorMesh.build(renderer,boxes):DirectPolygonMesh.surface(renderer,boxes,faces);}finally{active.remove();PolygonVoxelContext.current.remove();}}
 public static PreviewRenderer.BoxRenderResult outline(PreviewRenderer renderer,LittleBoxes boxes){active.set(boxes);try{return PolygonVoxelOutline.build(renderer,boxes);}finally{active.remove();}}
}
